def _lineal_parts(geom) -> list:
    """Return the LineString/MultiLineString parts of an intersection."""
    return _contact_parts(geom)[0]


def _point_parts(geom) -> list:
    """Return the Point/MultiPoint parts of an intersection.

    Boundary intersections of polygons that only pinch together (and mixed
    contacts that are partly lineal, partly point) contain Point members.
    R2 dropped these, which let independent simplifications separate or
    cross at isolated contact vertices.
    """
    return _contact_parts(geom)[1]


def _contact_parts(geom) -> tuple:
    """Return ``(lineal_parts, point_parts)`` of a boundary intersection.

    Recurses into GeometryCollections (the result type when two polygon
    boundaries share edges AND touch at isolated points) and Multi* members.
    """
    lineal: list = []
    points: list = []

    def visit(node) -> None:
        kind = node.geom_type
        if kind == "LineString":
            if not node.is_empty:
                lineal.append(node)
        elif kind == "MultiLineString":
            lineal.extend(p for p in node.geoms if not p.is_empty)
        elif kind == "Point":
            if not node.is_empty:
                points.append(node)
        elif kind == "MultiPoint":
            points.extend(p for p in node.geoms if not p.is_empty)
        elif kind in ("GeometryCollection", "MultiPolygon"):
            for part in node.geoms:
                visit(part)
        # Polygon parts in a boundary intersection are not expected for
        # polygon boundaries (1-D input); they are ignored deliberately.

    visit(geom)
    return lineal, points

