def _pair_contact_safe(geom_a, geom_b, cand_a, cand_b) -> str | None:
    """Validate one neighbour pair's original contacts against candidates.

    ``geom_*`` are the original feature geometries, ``cand_*`` their packed
    candidates (the very same objects when a feature is unchanged). Returns
    ``None`` when safe, otherwise a stable reason string:

      * ``neighbour_overlap_new_area`` - candidates cover ground that the
        original two polygons did not BOTH cover (0 -> positive overlap, or
        extra area on top of an existing overlap);
      * ``neighbour_seam_uncovered`` - an original shared lineal seam is no
        longer fully covered by both candidate boundaries (a gap opened);
      * ``neighbour_contact_point_lost`` - an original isolated boundary
        contact point is no longer on both candidate boundaries;
      * ``neighbour_check_error`` - GEOS could not evaluate the pair, which
        is treated as unsafe (conservative whole-feature retention).
    """
    try:
        changed = cand_a is not geom_a or cand_b is not geom_b
        if changed:
            candidate_intersection = cand_a.intersection(cand_b)
            if candidate_intersection.area > NEW_OVERLAP_AREA_EPS:
                # Subtract the complete original intersection (which may be a
                # legitimate overlap for polygons on different height layers)
                # so only NEWLY shared interior area trips the guard.
                original_intersection = geom_a.intersection(geom_b)
                new_region = candidate_intersection.difference(
                    original_intersection
                )
                if new_region.area > NEW_OVERLAP_AREA_EPS:
                    return "neighbour_overlap_new_area"

        lineal_parts, point_parts = _contact_parts(
            geom_a.boundary.intersection(geom_b.boundary)
        )
        boundary_a, boundary_b = cand_a.boundary, cand_b.boundary
        for part in lineal_parts:
            if part.length < SEAM_MIN_LENGTH_M:
