            if (
                part.difference(boundary_a).length
                > CONTACT_COVERAGE_LENGTH_EPS
                or part.difference(boundary_b).length
                > CONTACT_COVERAGE_LENGTH_EPS
            ):
                return "neighbour_seam_uncovered"
        for point in point_parts:
            if not (
                point.intersects(boundary_a) and point.intersects(boundary_b)
            ):
                return "neighbour_contact_point_lost"
    except (ShapelyError, ValueError, TypeError):
        return "neighbour_check_error"
    return None


def _enforce_neighbour_safety(doc: dict, candidates: dict) -> dict:
    """Re-validate every candidate against its neighbours, falling back.

    Locking shared vertices keeps most contacts intact, but a per-ring
    Douglas-Peucker selection cannot in general be proven safe from contacts
    it never saw: shallow pinch points removed asymmetrically or chord
    cut-offs across a concave edge can still cross a neighbour. Whenever a
    pair cannot be shown safe, EVERY side of that pair that actually moved is
    retained complete and unchanged, and validation repeats (forcing is
    monotone). Pairs of unchanged features are safe by construction, so the
    loop always terminates with all remaining pairs validated.

    Candidate vertices are a subset of original vertices, hence candidate
    bounding boxes never grow: an STRtree over the ORIGINAL geometries with
    an ``intersects`` predicate finds every pair that could possibly interact
    (plus harmless bbox-only pairs), including across layers and heights.
    """
    keys: list = []
    original_components: list = []
    for layer_name in LAYER_NAMES:
        for index, feature in enumerate(doc["layers"][layer_name]):
            keys.append((layer_name, index))
            try:
                original_components.append(
                    _build_shapely_polygons(feature["polygons"])
                )
            except (ShapelyError, ValueError, TypeError):
                original_components.append(None)

    original_geoms: list = []
    for built in original_components:
        if built is None:
            original_geoms.append(None)
        elif len(built) == 1:
            original_geoms.append(built[0])
        else:
            original_geoms.append(MultiPolygon(built))

    live = [i for i, geom in enumerate(original_geoms) if geom is not None]
    tree = (
        STRtree([original_geoms[i] for i in live]) if live else None
    )

    def candidate_components(index: int):
        cand = candidates[keys[index]]
        if not cand["mobile"]:
            return original_components[index]
        if cand.get("geom_components") is None:
            cand["geom_components"] = _build_shapely_polygons(cand["polygons"])
        return cand["geom_components"]

    def candidate_geom(index: int, components):
        if not candidates[keys[index]]["mobile"]:
            return original_geoms[index]
        return components[0] if len(components) == 1 else MultiPolygon(components)

    stats = {
        "pairs_checked": 0,
        "iterations": 0,
        "features_forced": 0,
        "forced_reasons": {},
        "new_overlap_area_eps_m2": NEW_OVERLAP_AREA_EPS,
        "contact_coverage_length_eps_m": CONTACT_COVERAGE_LENGTH_EPS,
    }

    while True:
        stats["iterations"] += 1
        newly_forced: dict = {}

        # Build this round's candidate geometries; a feature whose own
        # candidate cannot even be constructed is conservatively retained.
        current_components: list = [None] * len(keys)
        for i in live:
            key = keys[i]
            cand = candidates[key]
            if not cand["mobile"]:
                current_components[i] = original_components[i]
                continue
            try:
                current_components[i] = candidate_components(i)
            except (ShapelyError, ValueError, TypeError):
                newly_forced.setdefault(i, "neighbour_check_error")
                current_components[i] = original_components[i]

        def force(index: int, reason: str) -> None:
            if candidates[keys[index]]["mobile"]:
                newly_forced.setdefault(index, reason)

        if tree is not None:
            for t_index in range(len(live)):
                i = live[t_index]
                if i in newly_forced:
                    continue
                comp_i = current_components[i]
                geom_i = candidate_geom(i, comp_i)
                try:
                    hits = [
                        int(j)
                        for j in tree.query(
                            original_geoms[i], predicate="intersects"
                        )
                    ]
                except (ShapelyError, ValueError, TypeError):
                    force(i, "neighbour_check_error")
                    continue
                for t_other in hits:
                    j = live[t_other]
                    if j <= i or j in newly_forced:
                        continue
                    cand_i = candidates[keys[i]]
                    cand_j = candidates[keys[j]]
                    if not cand_i["mobile"] and not cand_j["mobile"]:
                        continue
                    comp_j = current_components[j]
                    geom_j = candidate_geom(j, comp_j)
                    stats["pairs_checked"] += 1
                    reason = _pair_contact_safe(
                        original_geoms[i], original_geoms[j],
                        geom_i, geom_j,
                    )
                    if reason is not None:
                        force(i, reason)
                        force(j, reason)
                        if reason in newly_forced.values():
                            break
                if i in newly_forced:
                    # The current geometry is suspect; skip it as a neighbour
                    # driver this round. It becomes original before recheck.
                    pass

        # Components inside one MultiPolygon feature are neighbours too.
        for i in live:
            if i in newly_forced:
                continue
            cand = candidates[keys[i]]
            if not cand["mobile"]:
                continue
            orig_built = original_components[i]
            cand_built = current_components[i]
            if orig_built is None or len(orig_built) < 2:
                continue
            for a in range(len(orig_built)):
                for b in range(a + 1, len(orig_built)):
                    stats["pairs_checked"] += 1
                    reason = _pair_contact_safe(
                        orig_built[a], orig_built[b],
                        cand_built[a], cand_built[b],
                    )
                    if reason is not None:
                        force(i, reason)
                        break
                if i in newly_forced:
                    break

        if not newly_forced:
            break

        for i, reason in newly_forced.items():
            key = keys[i]
            cand = candidates[key]
            if not cand["mobile"]:
                continue
            cand["polygons"] = _copy_polygons(
                doc["layers"][key[0]][key[1]]["polygons"]
            )
            cand["status"] = "fallback"
            cand["distance"] = 0.0
            cand["reason"] = reason
            cand["mobile"] = False
            cand["geom_components"] = None
            stats["features_forced"] += 1
            stats["forced_reasons"][reason] = (
                stats["forced_reasons"].get(reason, 0) + 1
            )

    return stats


